from lib import *
S = SS('x73')
steps = [
    step("一次正常启动的时间线(--foo=bar --flag baz,application.properties 里有 app.v=from-file)。从 main() 第一行算起:约 201 ms 时 ApplicationStartingEvent(这时还没有 Environment),约 319 ms ApplicationEnvironmentPreparedEvent——监听器里已经能读到 app.v=from-file,配置文件在这个事件之前就加载好了;约 351 ms ApplicationContextInitializedEvent 和约 374 ms ApplicationPreparedEvent,这时 Bean 定义只有 5 个、6 个,isActive=false,Bean 还一个没创建;然后才 refresh:某个 Bean 的 @PostConstruct(约 523 ms)、SmartLifecycle.start()(约 544 ms)、ContextRefreshedEvent(这时 Bean 定义 56 个,isActive=true),紧接着 ApplicationStartedEvent 和 LivenessState.CORRECT。这之后才轮到 runner:R1 CommandLineRunner @Order(1) 拿到原始参数 [--foo=bar, --flag, baz];R2 ApplicationRunner @Order(2) 拿到解析后的 options=[flag, foo]、nonOption=[baz]、foo=[bar]、flag=[](--flag 后面的 baz 没有被当成它的值);没有 @Order 的 R3 排最后。三个 runner 都结束后才是 ApplicationReadyEvent 和 ReadinessState.ACCEPTING_TRAFFIC,最后 run() 返回。时间是单次运行的毫秒数,每次会抖动,顺序是稳定的。", t=tl(S(1)), mark=lidx(S(1), 'ApplicationEnvironmentPreparedEvent', 'ApplicationPreparedEvent', 'ApplicationStartedEvent', 'R2 ApplicationRunner'), done=lidx(S(1), 'ApplicationStartingEvent', 'ContextRefreshedEvent', 'ApplicationReadyEvent', 'ReadinessState'), b=bars([['ApplicationContextInitializedEvent 时的 Bean 定义数', 5, '5'], ['ApplicationPreparedEvent 时的 Bean 定义数', 6, '6'], ['ContextRefreshedEvent 时的 Bean 定义数', 56, '56']], 56, done=[2], mark=[0, 1]), kv=KV([['Starting', '还没有 Environment'], ['EnvironmentPrepared', '配置文件已加载,Bean 还没有'], ['Prepared', '定义已注册,还没 refresh'], ['Started → runners → Ready', 'runner 在 Started 与 Ready 之间']], ['Started → runners → Ready'])),
    step("四种登记监听器的方式,各自能收到什么。同一次运行里,[A] SpringApplication.addListeners(...) 收到 10 个事件(ApplicationStarting、EnvironmentPrepared、ContextInitialized、Prepared、ContextRefreshed、Started、AvailabilityChange、Ready、AvailabilityChange、ContextClosed);[B] @Component 的监听器只收到 6 个:ContextRefreshed、Started、AvailabilityChange、Ready、AvailabilityChange、ContextClosed,前面四个事件发生时它还不存在,永远收不到;[C] 写在 META-INF/spring.factories 里的 ApplicationListener 同样收到 10 个;[R] 写在 spring.factories 里的 SpringApplicationRunListener 不是事件,是 6 个回调:starting、environmentPrepared、contextPrepared、contextLoaded、started、ready,这次运行里每一个都和 A 里对应的事件在同一毫秒。想在 Environment 准备好之前插手(比如改配置来源),要用 A、C 或 R,@Component 太晚了。", t=tl(S(2)), mark=lidx(S(2), '[B] @Component'), done=lidx(S(2), '[A]', '[C]', '[R]'), b=bars([['[A] addListeners 收到的事件数', 10, '10'], ['[B] @Component 收到的事件数', 6, '6'], ['[C] spring.factories 的 ApplicationListener', 10, '10'], ['[R] SpringApplicationRunListener 的回调数', 6, '6']], 10, done=[0, 2, 3], mark=[1]), kv=KV([['addListeners / spring.factories', '能收到启动最早期的事件'], ['@Component', '只收到 Bean 创建之后的 6 个'], ['SpringApplicationRunListener', '6 个回调,不是事件'], ['要在 Environment 之前插手', '不能用 @Component']], ['@Component'])),
    step("启动失败时的事件与退出码。Bean 的 @PostConstruct 抛异常:事件走到 ApplicationPreparedEvent 为止,没有 ContextRefreshed、Started、runner,也没有 ContextClosed;ApplicationFailedEvent 的内容是 BeanCreationException,R 的 failed 回调同时触发,进程退出码 1。最后一个 runner 抛异常:ContextRefreshed、Started 和三个 runner 都已经走过,R3 抛出之后触发 ApplicationFailedEvent(IllegalStateException: boom in runner),再触发 ContextClosedEvent,退出码也是 1;ApplicationReadyEvent 没有发布,就是说 runner 抛异常的应用从来没有变成 ready。想自己决定退出码:SpringApplication.exit(ctx, () -> 42) 会先发布 ExitCodeEvent(exitCode=42),再关闭上下文(ContextClosedEvent),返回 42,System.exit 之后进程退出码是 42。", t=tl(S(3)), mark=lidx(S(3), 'ApplicationFailedEvent', 'boom in runner'), done=lidx(S(3), 'ExitCodeEvent', '退出码 42', 'SpringApplication.exit 返回'), b=bars([['@PostConstruct 抛异常:退出码', 1, '1'], ['runner 抛异常:退出码', 1, '1'], ['SpringApplication.exit(ctx, () -> 42):退出码', 42, '42'], ['正常启动并返回:退出码', 0, '0']], 42, done=[3], mark=[0, 1], cur=[2]), kv=KV([['Bean 初始化失败', 'Failed 事件,没有 ContextClosed,退出码 1'], ['runner 抛异常', 'Failed → ContextClosed,没有 Ready,退出码 1'], ['主动退出', 'ExitCodeEvent → ContextClosed → 自定义退出码'], ['runner 的位置', 'Started 之后、Ready 之前']], ['runner 抛异常'])),
    step("内嵌 Web 容器。同一个程序换成 Servlet 应用(Bean 定义 150 个),加一个返回 liveness / readiness 的 /state 接口,把最后一个 runner 改成睡 1500 ms,再从外部另一个进程不停地试着连接端口。外部客户端第一次连上端口在约 870 ms,比 ServletWebServerInitializedEvent(约 878 ms)还早,更早于三个 runner 开始(约 882 ms)。runner 睡眠期间,约 914 ms 发出的 GET /state 得到 HTTP 200,内容是 liveness=CORRECT readiness=REFUSING_TRAFFIC。runner 约 2388 ms 结束,紧接着 ApplicationReadyEvent 和 ReadinessState.ACCEPTING_TRAFFIC;之后再请求一次,readiness=ACCEPTING_TRAFFIC。也就是说端口开放和 readiness 是两回事:容器在 refresh 阶段就已经监听,慢的 runner 把「应用能接请求但自己声明还没 ready」的窗口拉长到 1500 ms。如果探针只测 TCP 端口,按这次的时间线它会比 readiness 早约 1500 ms通过(我没有在 K8s 里验证,这里只是读时间线)。", t=tl(S(4)), mark=lidx(S(4), '第一次连上端口', 'GET /state 收到响应', 'R3 慢 runner 结束'), done=lidx(S(4), 'ServletWebServerInitializedEvent', 'ApplicationReadyEvent', 'ReadinessState', 'runner 结束之后再请求'), b=bars([['外部客户端第一次连上端口(ms)', 870, '870'], ['ServletWebServerInitializedEvent(ms)', 878, '878'], ['GET /state 得到 REFUSING_TRAFFIC(ms)', 914, '914'], ['ApplicationReadyEvent(ms)', 2389, '2389']], 2389, done=[3], mark=[0, 2], cur=[1]), kv=KV([['端口', 'refresh 阶段就开了,早于 runner'], ['runner 期间', '请求能处理,readiness=REFUSING_TRAFFIC'], ['Ready', '所有 runner 结束之后'], ['只测端口的探针', '按时间线会早约 1500 ms通过(未在 K8s 验证)']], ['端口'])),
]
A = mkartx('x73', 73, 'Spring,Boot,SpringApplication,启动事件,ApplicationRunner,真实验证,动画演示',
    '实测 SpringApplication.run 的启动阶段:Starting、EnvironmentPrepared、ContextInitialized、Prepared、ContextRefreshed、Started、runner、Ready 的顺序与每一步时 Bean 定义数;@Component 监听器收不到前四个事件;runner 抛异常和 Bean 初始化失败时的事件与退出码;内嵌 Tomcat 的端口在 runner 之前就开了,慢 runner 期间 readiness 是 REFUSING_TRAFFIC。',
    '应用启动时到底按什么顺序触发了哪些事件?@Component 里写的监听器为什么收不到 ApplicationStartingEvent?runner 在 Ready 之前还是之后跑?慢的 runner 会不会让端口一直关着?这篇在 Spring Boot 4.0.8 上把每个阶段都打了点。',
    [('10 / 6', 'addListeners 与 spring.factories 的监听器收到 10 个事件,@Component 的监听器只收到 6 个'), ('5 → 6 → 56', 'ContextInitialized、Prepared、ContextRefreshed 三个时间点的 Bean 定义数'), ('870 ms vs 2388 ms', '外部客户端第一次连上端口,与 1500 ms 的慢 runner 结束,相差约 1500 ms')],
    [('事件的顺序', '<p>Starting → EnvironmentPrepared → ContextInitialized → Prepared → refresh → ContextRefreshed → Started → runners → Ready;配置文件在 EnvironmentPrepared 之前加载好。</p>'),
     ('谁能收到哪些事件', '<p>addListeners 与 spring.factories 能收到全部;@Component 的监听器只收到 refresh 之后的 6 个。</p>'),
     ('失败与退出码', '<p>Bean 初始化失败与 runner 抛异常都是退出码 1,前者没有 ContextClosed,后者没有 Ready;SpringApplication.exit 可以自定义退出码。</p>'),
     ('端口与 readiness', '<p>内嵌容器的端口在 runner 之前就开放;runner 期间 readiness 是 REFUSING_TRAFFIC,Ready 事件之后才变 ACCEPTING_TRAFFIC。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的单个程序(第一至三节用 spring-boot-starter,非 Web 模式;第四节用 spring-boot-starter-webmvc,内嵌 Tomcat),每个场景一个独立 JVM;时间是从 main() 第一行起算的毫秒数,单次运行,每次会有抖动;Bean 定义数取自 getBeanDefinitionCount();第四节的外部客户端是另一个 Python 进程,用 5 ms 间隔轮询端口,所以「第一次连上」的时间有几毫秒的误差',
     '没有验证:测试里的 SpringBootTest 启动顺序;虚拟线程与 @Async 对启动事件的影响;Actuator 的 /health/readiness 读的是不是这里的 ApplicationAvailability(本篇没有引入 Actuator);Kubernetes 里 TCP 探针与 readiness 探针的实际表现;有 BootstrapRegistry、DefaultBootstrapContext 的场景(Spring Cloud 配置中心早期阶段);GraalVM 原生镜像下的启动顺序'],
    '启动阶段与事件')
